The `connect` and `disconnect` functions don't have error handling for the API calls themselves. If the MCP server fails to connect or disconnect, the error should be properly handled and communicated. Consider wrapping the `create` call and client operations in try-catch blocks and returning appropriate error responses or throwing meaningful errors.
```suggestion
    try {
      const s = await state()
      const client = s.clients[name]
      if (client) {
        await client.close().catch((error) => {
          log.error("Failed to close MCP client", { name, error })
          s.status[name] = {
            status: "disabled",
            error: error instanceof Error ? error.message : String(error),
          }
        })
        delete s.clients[name]
      }
      if (!s.status[name] || s.status[name].status !== "disabled") {
        s.status[name] = { status: "disabled" }
      }
    } catch (error) {
      log.error("Error during MCP disconnect", { name, error })
      const s = await state()
      s.status[name] = {
        status: "disabled",
        error: error instanceof Error ? error.message : String(error),
      }
    }
  }

  export async function connect(name: string) {
    try {
      const cfg = await Config.get()
      const config = cfg.mcp ?? {}
      const mcp = config[name]
      if (!mcp) {
        log.error("MCP config not found", { name })
        return
      }

      const result = await create(name, { ...mcp, enabled: true })
      if (!result) {
        const s = await state()
        s.status[name] = {
          status: "failed",
          error: "Failed to connect",
        }
        return
      }

      const s = await state()
      s.status[name] = result.status
      if (result.mcpClient) {
        s.clients[name] = result.mcpClient
      }
    } catch (error) {
      log.error("Error during MCP connect", { name, error })
      const s = await state()
      s.status[name] = {
        status: "failed",
        error: error instanceof Error ? error.message : String(error),
      }
    }
```

Potential null reference: The code uses `status.data!` with a non-null assertion operator. If `sdk.client.mcp.status()` returns data as null or undefined, this will cause a runtime error. Consider adding proper null checking or error handling before setting the sync data.
```suggestion
          if (status.data != null) {
            sync.set("mcp", status.data)
          }
```
